pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 amount, uint256 reentrantCount) public {
        // Restrict parameters to admissible domain: non-zero address, non-zero amount, bounded re-entry count
        vm.assume(target != address(0));
        vm.assume(amount > 0);
        vm.assume(reentrantCount > 0 && reentrantCount <= 10);

        // Deploy a minimal re-entrant attacker that calls addToBalance multiple times during withdrawBalance
        Reenterer attacker = new Reenterer(c, reentrantCount);
        address attackerAddr = address(attacker);

        // Fund the attacker with enough Ether to deposit multiple times
        uint256 totalDeposit = amount * reentrantCount; // enough to cover reentrant calls
        vm.deal(attackerAddr, totalDeposit + 1 ether); // extra for gas

        // Also provide some Ether to a separate target user for comparison
        vm.deal(target, amount);

        // Step 1: Perform legitimate deposits via addToBalance on the attacker and another target
        vm.prank(attackerAddr);
        c.addToBalance{value: totalDeposit}();

        vm.prank(target);
        c.addToBalance{value: amount}();

        // Record total Ether that has flowed INTO the contract via addToBalance calls so far
        uint256 totalPaymentsIn = totalDeposit + amount;

        // Step 2: Trigger withdrawBalance from the attacker, causing reentrant calls to addToBalance
        // The attacker's receive() calls addToBalance with amount wei each time during the withdrawal
        vm.prank(attackerAddr);
        c.withdrawBalance();

        // Step 3: Assert invariant: userBalance[target] must NOT exceed totalPaymentsIn
        // In the reference contract, reentrant calls are blocked, so balances remain consistent.
        // In the buggy contract, reentrant calls can manipulate balances during withdrawal,
        // potentially inflating target's balance beyond the total deposited by all parties.
        assertTrue(c.getBalance(target) <= totalPaymentsIn);
    }
}

contract Reenterer {
    C public targetContract;
    uint256 public count;
    uint256 public remaining;

    constructor(C _target, uint256 _count) {
        targetContract = _target;
        count = _count;
        remaining = _count;
    }

    receive() external payable {
        if (remaining > 0) {
            remaining--;
            // Re-entrant call to addToBalance with a small amount
            // The attacker's balance is drained during withdrawBalance,
            // but the re-entrant call re-adds to the balance, enabling drain-repeat.
            // We use a fixed amount (1 wei) funded by the remaining gas stipend.
            targetContract.addToBalance{value: 1}();
        }
    }
}

