import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 + amount2 >= amount1); // prevent overflow
        vm.assume(amount1 + amount2 >= amount2);
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        // Deploy a reentrant attacker that calls addToBalance again during its receive
        Reenterer attacker = new Reenterer(c);
        vm.deal(address(attacker), amount1 + amount2);

        // Record balances before any call
        uint256 balBefore = address(c).balance;
        uint256 sumBefore = c.getBalance(caller) + c.getBalance(address(attacker));

        vm.prank(address(attacker));
        attacker.attack{value: amount1}(amount2);

        // After the attack, compute total userBalance sum and compare to contract balance
        uint256 balAfter = address(c).balance;
        uint256 sumAfter = c.getBalance(caller) + c.getBalance(address(attacker));

        // Invariant: contract balance must always match the sum of all userBalances
        assertEq(balAfter - balBefore, sumAfter - sumBefore, "balance mismatch after addToBalance");
    }
}

contract Reenterer {
    C target;
    uint256 private extra;
    bool private reentered;
    constructor(C _target) { target = _target; }
    function attack(uint256 _extra) external payable {
        extra = _extra;
        reentered = false;
        target.addToBalance{value: msg.value - extra}();
    }
    receive() external payable {
        if (!reentered && extra > 0) {
            reentered = true;
            target.addToBalance{value: extra}();
        }
    }
}

