contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 reentrantCallAmount) public {
        // Bound deposit to avoid overflow and ensure it is non-trivial
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        reentrantCallAmount = bound(reentrantCallAmount, 0, depositAmount);

        // Deploy a reentrant attacker that will call back into addToBalance during withdrawBalance
        ReentrantAttacker attacker = new ReentrantAttacker(c, reentrantCallAmount);

        // Fund attacker with deposit amount
        vm.deal(address(attacker), depositAmount);

        // Attacker makes a legitimate deposit
        attacker.deposit{value: depositAmount}();

        // Attacker triggers withdraw, which will call back into addToBalance in the fallback
        attacker.attack();

        // After the sequence, the attacker's balance should equal only what they legitimately deposited.
        // The total deposited by the attacker is depositAmount (the initial deposit) + reentrantCallAmount (if reentrant call succeeds).
        // Because the reentrant call does not provide Ether, the balance should not increase beyond depositAmount.
        uint256 balance = c.getBalance(address(attacker));
        // Property: balance must equal the sum of legitimate deposits (only depositAmount had Ether).
        assertTrue(balance == depositAmount);
    }
