pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialDeposit, uint256 attackAmount) public {
        // Bound amounts to avoid overflow and keep Ether transfers feasible
        initialDeposit = bound(initialDeposit, 1 ether, 100 ether);
        attackAmount = bound(attackAmount, 0.1 ether, 10 ether);
        vm.assume(attackAmount <= initialDeposit);

        // Deploy the reentrant attacker with a reference to c and total attack ether
        Attacker attacker = new Attacker(c);
        address attackerAddr = address(attacker);

        // Fund attacker with initial deposit + attack amount
        uint256 totalFunds = initialDeposit + attackAmount;
        vm.deal(attackerAddr, totalFunds);

        // Attacker starts the attack: sends initialDeposit to addToBalance via its attack function
        vm.prank(attackerAddr);
        attacker.attack{value: initialDeposit}(attackAmount);

        // After the attack, compute the expected remaining balance for the attacker in C.
        // The attacker used initialDeposit for the top-level addToBalance and attackAmount for the reentrant call.
        // In the reference (non-reentrant), the reentrant call is blocked.
        // So only the top-level deposit (initialDeposit) is recorded.
        // The reentrant call's value (attackAmount) is returned to the attacker because the reentrant addToBalance reverts
        // (the modifier prevents reentrancy). The attacker ends up with its original totalFunds minus initialDeposit.
        // In the buggy version, both deposits succeed, overwriting the balance atomically (the second overwrites the first),
        // but we can detect the discrepancy by checking the invariant that the userBalance plus the attacker's remaining
        // Ether equals the total sent via successful addToBalance calls.

        // Read final userBalance for attacker
        uint256 finalBalance = c.getBalance(attackerAddr);
        uint256 attackerRemainingEther = attackerAddr.balance;

        // In the reference: only initialDeposit was accepted, finalBalance = initialDeposit,
        // attackerRemainingEther = totalFunds - initialDeposit = attackAmount.
        // Sum = initialDeposit + attackAmount = totalFunds.
        // In the buggy: both deposits accepted, but the second overwrites the first,
        // so finalBalance likely equals attackAmount (the last write) or some corrupted value,
        // and attackerRemainingEther = totalFunds - initialDeposit - attackAmount = 0.
        // Sum = attackAmount + 0 = attackAmount, which is less than totalFunds.
        // However, the attacker could have withdrawn if we triggered a withdraw, but we didn't.
        // A robust invariant: sum of finalBalance and attacker's current Ether balance
        // must equal its initial funding minus any Ether permanently lost in the contract's refund logic?
        // Actually, the correct invariant is: after any non-reverting operation, the sum of user balances
        // in the contract equals the contract's Ether balance (handled carefully).
        // But simpler: the sum of the attacker's userBalance and the attacker's own Ether balance
        // must equal the original totalFunds minus any Ether sent to C and not withdrawable?
        // We can assert: finalBalance + attackerRemainingEther == totalFunds.
        // In ref: initialDeposit + attackAmount = totalFunds. True.
        // In bug: attackAmount (if overwritten) + 0 = attackAmount < totalFunds. Violates.
        assertTrue(finalBalance + attackerRemainingEther == totalFunds);
    }
}

contract Attacker {
    C target;
    uint256 reentrantValue;
    bool reenterDone;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 _reentrantValue) external payable {
        reentrantValue = _reentrantValue;
        // Top-level deposit using the received Ether (msg.value)
        target.addToBalance{value: msg.value}();
    }

    receive() external payable {
        if (!reenterDone) {
            reenterDone = true;
            // Reentrant call: try to addToBalance with the attacker's remaining Ether
            // This call will succeed only in the buggy version (modifier allows reentrancy)
            target.addToBalance{value: reentrantValue}();
        }
    }
}

